from base_sensor import BaseVirtualSensor

class MPU6050_Simulator(BaseVirtualSensor):
    REG_WIDTH = 16

    def __init__(self):
        super().__init__()
        self.regs = {0x19: 0x00, 0x1A: 0x00, 0x1B: 0x00, 0x1C: 0x00, 0x3B: 0x00, 0x3C: 0x00, 0x3D: 0x00, 0x3E: 0x00, 0x3F: 0x00, 0x40: 0x00, 0x6B: 0x40, 0x75: 0x68}

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr in self.regs:
            if nbytes == 1:
                return (self.regs[addr] & 0xFF00) >> 8
            else:
                return self.regs[addr]
        else:
            return 0

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr in self.regs and self.regs[addr] != 0x00 and self.regs[addr] != 0x40 and self.regs[addr] != 0x68:
            if nbytes == 1:
                self.regs[addr] = (self.regs[addr] & 0x00FF) | ((data & 0xFF) << 8)
            else:
                self.regs[addr] = data

